#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The console-only steps of the circle invite links (issue #61): the invite domain's certificate in us-east-1,
# its validation record and the domain's CNAME at SiteGround (matthewcelia.com's DNS host), the deploy, a check
# that the domain serves the association file and the fallback page, and Associated Domains on the App ID.
#
#   infra/scripts/circles-wizard.sh                  # from the start
#   WIZARD_FROM=3 infra/scripts/circles-wizard.sh    # resume at stage 3 (e.g. waiting on the certificate)
#
# Run infra/scripts/accounts-wizard.sh first: this one reuses its budget address, bootstrap check and deploy.
# The certificate is requested here, outside the stack, so nothing in CloudFormation waits on a DNS change and
# us-east-1 needs no CDK bootstrap: the stack stays in us-west-2 and hands CloudFront the certificate by ARN.
# Its ARN goes to ~/keys/birdjournal.env (it names the account, so not the public repo).

run_wizard() {

TOTAL_STAGES=7
WIZARD_FROM="${WIZARD_FROM:-1}"

for tool in aws jq dig curl; do
  command -v "$tool" >/dev/null 2>&1 || { printf '%s is required: brew install %s\n' "$tool" "$tool" >&2; exit 1; }
done

INFRA_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
mkdir -p "$HOME/keys"
ENV_FILE="$HOME/keys/birdjournal.env"
CERT_REGION="us-east-1" # CloudFront only takes certificates from here
STACK_REGION="us-west-2"
export AWS_PROFILE="${AWS_PROFILE:-lsvr-admin}"
DOMAIN=$(jq -r '.context.inviteDomain' "$INFRA_DIR/cdk.json")
ZONE="${DOMAIN#*.}"   # matthewcelia.com, the zone SiteGround hosts
HOST="${DOMAIN%%.*}"  # birdquest, the record's name inside it
BUNDLE_ID="com.matthewcelia.mybirdjournal"
SITEGROUND="https://my.siteground.com/websites/list"

# Fail before the browser work, not after it.
AWS_ACCOUNT=$(aws sts get-caller-identity --query Account --output text 2>/dev/null) || {
  printf 'AWS profile %s has no working credentials (aws sso login --profile %s?). Fix that, then re-run.\n' \
    "$AWS_PROFILE" "$AWS_PROFILE" >&2
  exit 1
}

# begin "Name" starts the next stage, or skips it (returning 1) when it comes before WIZARD_FROM.
begin() {
  if (( _STAGE_INDEX + 1 < WIZARD_FROM )); then _STAGE_INDEX=$((_STAGE_INDEX + 1)); return 1; fi
  stage "$1"
}

# certificate_arn: the saved ARN, from this run or an earlier one.
certificate_arn() { printf '%s' "${INVITE_CERTIFICATE_ARN:-$(_existing INVITE_CERTIFICATE_ARN || true)}"; }

certificate_status() {
  aws acm describe-certificate --region "$CERT_REGION" --certificate-arn "$(certificate_arn)" \
    --query 'Certificate.Status' --output text 2>/dev/null || echo "UNKNOWN"
}

# siteground_name FQDN: the Name to type in SiteGround's zone editor, which appends the zone itself.
siteground_name() { local name="${1%.}"; printf '%s' "${name%."$ZONE"}"; }

stack_output() {
  aws cloudformation describe-stacks --region "$STACK_REGION" --stack-name BirdJournal \
    --query "Stacks[0].Outputs[?OutputKey=='$1'].OutputValue" --output text 2>/dev/null
}

banner "BirdJournal: circle invite links ($DOMAIN)"

if begin "AWS Certificate Manager: request the certificate for $DOMAIN"; then
  say "CloudFront serves https://$DOMAIN with a certificate from $CERT_REGION, validated by a DNS record."
  note "Account $AWS_ACCOUNT · profile $AWS_PROFILE · region $CERT_REGION"
  existing=$(aws acm list-certificates --region "$CERT_REGION" \
    --certificate-statuses PENDING_VALIDATION ISSUED \
    --query "CertificateSummaryList[?DomainName=='$DOMAIN'].CertificateArn | [0]" --output text)
  if [[ -n "$existing" && "$existing" != "None" ]]; then
    note "Found one already: $existing"
    write_env INVITE_CERTIFICATE_ARN "$existing"
  elif confirm "Request a certificate for $DOMAIN in $CERT_REGION now?"; then
    arn=$(aws acm request-certificate --region "$CERT_REGION" --domain-name "$DOMAIN" \
      --validation-method DNS --idempotency-token birdjournalinvites \
      --tags Key=project,Value=birdjournal --query CertificateArn --output text)
    write_env INVITE_CERTIFICATE_ARN "$arn"
  else
    warn "Nothing to do without a certificate; re-run when ready."
    exit 1
  fi
  pause
fi

if begin "SiteGround: the certificate's validation record"; then
  say "ACM proves the domain is yours by looking up a CNAME record. Add it at SiteGround."
  record=""
  for _ in $(seq 1 30); do
    record=$(aws acm describe-certificate --region "$CERT_REGION" --certificate-arn "$(certificate_arn)" \
      --query 'Certificate.DomainValidationOptions[0].ResourceRecord.[Name,Value]' --output text 2>/dev/null || true)
    [[ -n "$record" && "$record" != "None" ]] && break
    sleep 2 # ACM takes a few seconds to publish the record after the request
  done
  [[ -n "$record" && "$record" != "None" ]] || { warn "ACM hasn't published the record yet; resume with WIZARD_FROM=2."; exit 1; }
  read -r VALIDATION_NAME VALIDATION_VALUE <<<"$record"
  open_url "$SITEGROUND"
  step "Websites → the site for $ZONE → Site Tools → Domain → DNS Zone Editor."
  step "Pick $ZONE in the domain list, then the CNAME tab."
  step "Name: $(siteground_name "$VALIDATION_NAME")"
  note "  (SiteGround adds .$ZONE itself; the full name is ${VALIDATION_NAME%.})"
  step "Resolves to: ${VALIDATION_VALUE%.}"
  step "TTL: leave the default → Create."
  note "Keep this record for good: ACM renews the certificate each year by looking it up again."
  pause "Press Enter once the record is created."
fi

if begin "Wait for the certificate to be issued"; then
  say "ACM checks the record every few minutes; it usually issues within 5 to 30 minutes."
  status=$(certificate_status)
  waited=0
  while [[ "$status" == "PENDING_VALIDATION" ]] && (( waited < 1800 )); do
    printf '\r  %s%s · waited %d min%s ' "$DIM" "$status" $((waited / 60)) "$RESET"
    sleep 30; waited=$((waited + 30))
    status=$(certificate_status)
  done
  printf '\n'
  case "$status" in
    ISSUED) printf '  %s✓ issued%s %s\n' "$GREEN" "$RESET" "$(certificate_arn)" ;;
    PENDING_VALIDATION)
      warn "Still pending after 30 minutes. Check the record at SiteGround (dig +short CNAME <name>),"
      warn "then resume with WIZARD_FROM=3 infra/scripts/circles-wizard.sh"
      exit 1 ;;
    *)
      warn "The certificate is $status. Delete it in the ACM console ($CERT_REGION) and start over:"
      warn "remove INVITE_CERTIFICATE_ARN from $ENV_FILE, then infra/scripts/circles-wizard.sh"
      exit 1 ;;
  esac
  pause
fi

if begin "Deploy the stack with the invite site"; then
  say "infra/scripts/deploy.sh runs the template tests, checks the shared us-west-2 bootstrap (it never"
  say "bootstraps), deploys CloudFront, the site bucket and the circle routes, and rewrites AccountServer.json."
  [[ "$(certificate_status)" == "ISSUED" ]] || { warn "The certificate isn't issued yet: resume with WIZARD_FROM=3."; exit 1; }
  if confirm "Deploy BirdJournal to $AWS_ACCOUNT / $STACK_REGION now?"; then
    INVITE_CERTIFICATE_ARN="$(certificate_arn)" "$INFRA_DIR/scripts/deploy.sh"
  else
    SKIPPED+=("deploy: infra/scripts/deploy.sh, then WIZARD_FROM=5 infra/scripts/circles-wizard.sh")
    finish; exit 0
  fi
  pause
fi

if begin "SiteGround: point $DOMAIN at CloudFront"; then
  TARGET=$(stack_output InviteDistributionDomain)
  [[ -n "$TARGET" && "$TARGET" != "None" ]] || { warn "No InviteDistributionDomain output: deploy first (WIZARD_FROM=4)."; exit 1; }
  open_url "$SITEGROUND"
  step "Site Tools → Domain → DNS Zone Editor → $ZONE → CNAME tab."
  step "Name: $HOST"
  step "Resolves to: $TARGET"
  step "TTL: leave the default → Create."
  note "An A record for $HOST already there? Delete it first: a name can't have both."
  pause "Press Enter once the record is created."
fi

if begin "Check the invite domain"; then
  say "Waiting for $DOMAIN to resolve, then fetching the association file and an invite link."
  for _ in $(seq 1 40); do
    [[ -n "$(dig +short "$DOMAIN" CNAME)" ]] && break
    sleep 15
  done
  note "$DOMAIN → $(dig +short "$DOMAIN" CNAME)"
  aasa_url="https://$DOMAIN/.well-known/apple-app-site-association"
  type=$(curl -fsS -o /dev/null -w '%{content_type}' "$aasa_url" 2>/dev/null || echo "unreachable")
  if [[ "$type" == application/json* ]] && curl -fsS "$aasa_url" | jq -e '.applinks.details[0].appIDs[0]' >/dev/null; then
    printf '  %s✓%s %s (%s)\n' "$GREEN" "$RESET" "$aasa_url" "$type"
  else
    warn "$aasa_url answered '$type'. DNS may still be spreading: resume with WIZARD_FROM=6 in a few minutes."
    SKIPPED+=("invite domain check: WIZARD_FROM=6 infra/scripts/circles-wizard.sh")
  fi
  if curl -fsS "https://$DOMAIN/i/wizard-check" 2>/dev/null | grep -q "invited to a circle"; then
    printf '  %s✓%s https://%s/i/… shows the fallback page\n' "$GREEN" "$RESET" "$DOMAIN"
  else
    warn "https://$DOMAIN/i/… didn't show the fallback page yet."
  fi
  note "Apple's CDN caches the file; it can take a day to pick up a change:"
  note "  curl https://app-site-association.cdn-apple.com/a/v1/$DOMAIN"
  pause
fi

if begin "Apple: Associated Domains on the App ID"; then
  say "The app's entitlement (applinks:$DOMAIN) needs the capability on its App ID for device and"
  say "TestFlight builds. Xcode's automatic signing may have switched it on already."
  open_url "https://developer.apple.com/account/resources/identifiers/list"
  step "Open the App ID $BUNDLE_ID → Capabilities → tick 'Associated Domains' → Save → Confirm."
  note "Already ticked? Nothing to do. Profiles regenerate on the next Xcode or Xcode Cloud build."
  pause "Press Enter once Associated Domains is on."
fi

finish
note "on a device: open an invite link from Messages (it opens the join screen), and in Safari's private"
note "tab paste one (it shows the fallback page); the Circle tab's QR code scans to the same link."
printf '\n'
}

run_wizard "$@"; exit
